let rosterTeamId=0;
const clampMorale=n=>Math.max(0,Math.min(100,Math.round(n)));
function moraleDetails(p,club){const starter=club?club.roster.indexOf(p)<5:false,games=club?club.w+club.l:0;const winning=games?Math.round((club.w/games-.5)*24):0;const role=club?(starter?8:p.ovr>=80?-14:p.ovr>=74?-7:0):-10;const security=club?(p.contractThrough>=state.year+1?8:0):-8;const change=p.moraleAdjustment||0;const happiness=clampMorale(65+winning+role+change);const focus=clampMorale(70+Math.round(winning/2)+Math.round(role/2)+Math.round(change/2));const satisfaction=clampMorale(65+role+security+change);const score=clampMorale((happiness+focus+satisfaction)/3);return{score,happiness,focus,satisfaction,label:score>=80?'Thriving':score>=65?'Content':score>=45?'Unsettled':'Unhappy',reasons:[club?(starter?'Starting role boosts satisfaction':role<0?'Wants a larger role':'Comfortable in a reserve role'):'Searching for a team',games?(winning>0?'Winning record lifts spirits':winning<0?'Losing record weighs on morale':'Team results are balanced'):'A fresh season',security>0?'Longer contract provides security':club?'On an annual agreement':'No contract security',...(change?['Recent '+(change>0?'positive':'difficult')+' change; impact fades with games']:[])]}}
function moraleBadge(p,club){const m=moraleDetails(p,club),mood=m.score>=70?'happy':m.score>=40?'neutral':'sad',mouth=mood==='happy'?'M8 14 Q12 19 16 14':mood==='neutral'?'M8 15 H16':'M8 17 Q12 12 16 17';return `<button class="morale-badge morale-face-badge morale-${mood}" onclick="profile(${p.id})" aria-label="${escapeHTML(p.name)}: ${m.score} morale, ${m.label}. Open player profile" title="${escapeHTML(m.reasons.join('. '))}"><svg class="morale-face-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true" focusable="false"><circle cx="12" cy="12" r="10"/><circle cx="8.5" cy="9" r=".8" fill="currentColor" stroke="none"/><circle cx="15.5" cy="9" r=".8" fill="currentColor" stroke="none"/><path d="${mouth}"/></svg><span>${m.score}<small>${m.label}</small></span></button>`}
function moraleProfile(ctx){const m=moraleDetails(ctx.p,ctx.club);return playerCard('PLAYER MORALE',`<div class="morale-heading"><strong class="pp-value">${m.score} / 100</strong><span>${m.label}</span></div><div class="pp-rating-bars">${[['Happiness',m.happiness],['Focus',m.focus],['Satisfaction',m.satisfaction]].map(([label,n])=>`<div><span>${label}</span><meter min="0" max="100" value="${n}">${n}</meter><strong>${n}</strong></div>`).join('')}</div><ul class="morale-reasons">${m.reasons.map(r=>`<li>${r}</li>`).join('')}</ul>`)}
const basePlayerOverview=playerOverview;playerOverview=ctx=>basePlayerOverview(ctx)+moraleProfile(ctx);
function rosterTeamRatings(club){
 const players=club.roster;if(!players.length)return {age:null,overall:null,offense:null,defense:null};
 const mean=(list,score)=>list.reduce((sum,p)=>sum+score(p),0)/list.length;
 const weighted=score=>{const starters=players.slice(0,5),bench=players.slice(5);return Math.round(bench.length?mean(starters,score)*.8+mean(bench,score)*.2:mean(starters,score))};
 const skill=keys=>p=>{const a=withBasketballAttributes(p).attributes;return keys.reduce((sum,key)=>sum+a[key],0)/keys.length};
 return {age:mean(players,p=>p.age),overall:weighted(p=>p.ovr),offense:weighted(skill(['lay','post','dnk','fg','tp','ft','drb','pss','oiq'])),defense:weighted(skill(['per','rim','stl','sbl','reb','diq']))};
}
function rosterTeamSummary(club){const values=rosterTeamRatings(club);return '<div class="roster-team-summary" aria-label="Team roster summary">'+[['age','Average age','All rostered players, including injured players.'],['overall','Team overall','80% starting-five average + 20% bench average, matching the dashboard team rating.'],['offense','Overall offense','Shooting, finishing, ball handling, passing and offensive IQ; 80% starters, 20% bench.'],['defense','Overall defense','Perimeter and rim defense, steals, blocks, rebounding and defensive IQ; 80% starters, 20% bench.']].map(([key,label,help])=>'<div title="'+help+'"><span>'+label+'</span><strong>'+(values[key]===null?'—':key==='age'?values[key].toFixed(1):ratingMarkup(values[key]))+'</strong></div>').join('')+'</div>'}
const baseRoster=roster;
roster=function(free=false){if(free)return baseRoster(true);const club=state.teams.find(t=>t.id===rosterTeamId)||team(),own=club.id===controlledTeamId();return `<section class="panel roster-panel"><div class="panelhead roster-heading"><div class="roster-brand">${teamLogo(club)}<div><h2>${escapeHTML(club.city+' '+club.name)}</h2><span class="muted">${club.roster.length} / ${rosterMaximum()} players · ${own?'Your team':'Viewing roster'}</span></div></div><label class="roster-switch">View team<select aria-label="Switch roster team" onchange="rosterTeamId=Number(this.value);render()">${state.teams.map(t=>`<option value="${t.id}" ${t.id===club.id?'selected':''}>${escapeHTML(t.city+' '+t.name)}${t.id===controlledTeamId()?' (Your team)':''}</option>`).join('')}</select></label></div>${rosterTeamSummary(club)}<div class="scroll"><table><thead><tr><th>Player</th><th>POS</th><th>AGE</th><th>OVR</th><th>POT</th><th>MORALE</th><th>PPG</th><th>SALARY</th><th>CONTRACT</th><th>ACTIONS</th></tr></thead><tbody>${club.roster.map((p,i)=>`<tr class="${injuryDays(p)?'injured-player':''}"><td><button class="namebutton" onclick="profile(${p.id})">${escapeHTML(p.name)}<small class="roster-player-meta"><span>${injuryDays(p)?'Inactive / IR · '+injuryDays(p)+' days':courtPositions().some(pos=>rotationFromClub(club).depth[pos][0]===p.id)?'Starter':'Bench'}</span><span class="roster-archetype">${escapeHTML(archetypeProfile(p).name)}</span></small></button></td><td>${p.pos}</td><td>${p.age}</td><td>${ratingMarkup(p.ovr)}</td><td>${ratingMarkup(p.pot)}</td><td>${moraleBadge(p,club)}</td><td>${p.gp?(p.pts/p.gp).toFixed(1):'—'}</td><td>${money(p.salary)}</td><td>${p.contractThrough>=state.year?'Through '+p.contractThrough:'Annual'}</td><td><div class="actions roster-actions">${own?`${injuryDays(p)?'<span class="injury-status">Out — 0 minutes</span>':i>=5?`<button onclick="promote(${p.id})">Start</button>`:'<span class="tag">Starting 5</span>'}<button onclick="playerTradeAction(${p.id})">Trade</button><button onclick="extendPlayerContract(${p.id})">Extend contract</button><button onclick="releasePlayer(${p.id})">Release</button>`:`<button onclick="profile(${p.id})">Profile</button><button onclick="playerTradeAction(${p.id})">Trade for</button>`}</div></td></tr>`).join('')}</tbody></table></div></section>${own?baseRoster(false).slice(baseRoster(false).indexOf('<div class="panel"><div class="panelhead"><h2>Game plan')):''}`};
function extensionQuote(p){return Math.round(p.salary*1.05*10)/10}
function extendPlayerContract(id){const c=playerContext(id);if(!c?.own)return;const p=c.p,quote=extensionQuote(p);if(negotiationStatus(p).refuses){titleModal('Negotiations refused',`<p>${escapeHTML(p.name)} is declining extension discussions. They may finish the current contract or reconsider if circumstances improve.</p><button onclick="profile(${id})">View morale</button>`);return}titleModal('Extend contract',`<p><strong>${escapeHTML(p.name)}</strong> · ${POSITION_NAMES[p.pos]}</p><p>Annual salary: ${money(p.salary)} → <strong>${money(quote)}</strong>. The new salary takes effect immediately. Morale-based demand: ${Math.round(negotiationStatus(p).premium*100)}% raise.</p><form onsubmit="confirmContractExtension(event,${id})"><label class="roster-switch">Future seasons<select name="years">${contractTerms().filter(n=>state.year+n>Math.max(state.year,p.contractThrough||state.year)).map(n=>`<option value="${n}">${n} season${n>1?'s':''} · through ${state.year+n}</option>`).join('')}</select></label><p id="extension-error" role="alert"></p><p>Choose the total future seasons in the renewed agreement. Extensions cannot shorten an existing deal. Expiring contracts enter the offseason re-signing period after the draft.</p><div class="actions"><button type="button" onclick="profile(${id})">Back to profile</button><button class="primary" type="submit">Confirm extension</button></div></form>`)}
async function confirmContractExtension(event,id){event.preventDefault();const c=playerContext(id);if(!c?.own)return;const years=Number(event.target.elements.years.value),p=c.p,end=state.year+years,quote=extensionQuote(p),error=document.getElementById('extension-error');if(negotiationStatus(p).refuses){error.textContent='Player is currently declining extension discussions.';return}if(!contractTerms().includes(years)||end<=Math.max(state.year,p.contractThrough||state.year)){error.textContent='Choose an allowed term that extends the current agreement.';return}if(payroll()-p.salary+quote>financeRosterLimit()){error.textContent='This extension would exceed the roster spending limit.';return}const before={salary:p.salary,contractThrough:p.contractThrough,moraleAdjustment:p.moraleAdjustment};p.salary=quote;p.contractThrough=end;p.moraleAdjustment=Math.min(15,(p.moraleAdjustment||0)+6);const ok=await save();if(!ok){Object.assign(p,before);error.textContent='Could not save the extension. Please try again.';return}closeTitleModal();render();profile(id);toast('Contract extended through '+end)}
const oldContractProfile=playerContract;playerContract=function(ctx){const {p,own,club}=ctx;return playerCard('CONTRACT',`<strong class="pp-salary">${money(club?p.salary:freeAgentQuote(p))} <small>/ year</small></strong><p>${club?(p.contractThrough>=state.year?'Signed through '+p.contractThrough+' · '+(p.contractThrough-state.year+1)+' seasons including this season':'Annual agreement'):'Free agent'}</p>${own?`<button class="primary" onclick="extendPlayerContract(${p.id})">Extend contract</button>`:''}`)+playerCard('YOUR TEAM FINANCES',`<dl class="pp-ledger"><div><dt>Payroll</dt><dd>${money(payroll())}</dd></div><div><dt>Cap space</dt><dd>${money(salaryCap()-payroll())}</dd></div></dl>`)+playerCard('AGREEMENT TERMS','<p>Salary demands depend on morale and personality. Ecstatic players may accept a hometown discount; money-focused players still seek a premium. Players below 40 morale refuse extensions, and discontent players demand more. Extensions take effect immediately and follow the league contract salary and term limits. Expiring contracts enter offseason free agency after the draft. Waived guaranteed salary remains as dead cap through the contract end.</p>')};
const basePlay=play;play=function(a,b,stage){const result=basePlay(a,b,stage);for(const club of [state.teams[a],state.teams[b]])for(const p of club.roster){if(p.moraleAdjustment)p.moraleAdjustment-=Math.sign(p.moraleAdjustment)}return result};
const baseTrade=trade;trade=function(){const outgoing=Number(document.getElementById('out').value),incoming=Number(document.getElementById('into').value);baseTrade();if(team().roster.some(p=>p.id===incoming)&&!team().roster.some(p=>p.id===outgoing)){for(const id of [outgoing,incoming]){const p=playerContext(id)?.p;if(p){resetPlayerSituation(p);p.moraleAdjustment=-6}}save();render()}};
const baseSign=sign;sign=function(id){const wasFree=state.free.some(p=>p.id===id);baseSign(id);const c=playerContext(id);if(wasFree&&c?.own){resetPlayerSituation(c.p);c.p.moraleAdjustment=8;c.p.contractThrough=state.year+leagueRules().minContractYears-1;save();render()}};
const baseRelease=releasePlayer;releasePlayer=function(id){const wasOwn=playerContext(id)?.own;baseRelease(id);const c=playerContext(id);if(wasOwn&&c&&!c.club){resetPlayerSituation(c.p);c.p.moraleAdjustment=-12;delete c.p.contractThrough;save();render()}};
